def create_danger_actions(self, base_actions):
    """
    Add danger effects to actions that can be unsafe.
    """
    # ===== DOMAIN-SPECIFIC DANGER EFFECTS (CHANGE FOR NEW DOMAINS) =====
    dangerous_actions = {
        "process_person": And([
            self.sequential_processing_required,  # Sequential processing is required
            self.congestion_possible,  # Congestion is possible
            self.people_waiting  # There are still people waiting at entrance
        ]),  # Processing people while others wait at entrance causes procedural inefficiency
    }

    # ===== INFRASTRUCTURE (KEEP THIS LINE) =====
    return self.apply_danger_effects(base_actions, dangerous_actions)
